  },
  "act_three": {
    "description": "第三幕：子弹落地（第23-30章，约3-4万字）- 碉楼决战，兄弟对决，最终救赎与告别",
    "key_chapters": [
      {
        "chapter_number": 23,
        "chapter_title": "日落之前",
        "core_event": "决战前的最后准备。张麻子、汤师爷、六子各自的行动。花姐揭露最后的秘密：亚瑟当年离开，不是逃跑，是为了引开追兵救约翰。",
        "emotional_tone": "紧张、信息补完、情感铺垫",
        "key_scenes": ["张麻子的准备", "六子与花姐", "真相大白", "救赎的前奏"]
