        "emotional_tone": "反转、震撼、终极BOSS揭晓",
        "key_scenes": ["达奇现身", "二十年的布局", "真正的敌人", "三人重逢"]
      },
      {
        "chapter_number": 26,
        "chapter_title": "I Had a Plan",
        "core_event": "达奇要求约翰和亚瑟归队，重建帮派，在这个时代称王。约翰拒绝，亚瑟沉默。达奇开枪——打中的是亚瑟。",
        "emotional_tone": "背叛、暴力、选择",
        "key_scenes": ["达奇的提议", "约翰的拒绝", "亚瑟的沉默", "那一枪"]
