        "key_scenes": ["快拔枪训练", "六子的天赋", "美式居合的秘密", "六子的身世线索"]
      },
      {
        "chapter_number": 7,
        "chapter_title": "来者不善",
        "core_event": "黄四郎派人刺杀张麻子。张麻子用西部枪法反杀，但故意留下活口。活口带话回去：'问你们老板，还记得塔希提岛吗？'",
        "emotional_tone": "血腥、暴力美学、试探",
        "key_scenes": ["夜间伏击", "张麻子的枪法", "留活口传话", "黄四郎的反应——他愣住了"]
      },
      {
        "chapter_number": 8,
        "chapter_title": "惊喜",
        "core_event": "黄四郎收到消息后独自枯坐。他打开保险柜，取出一把锈迹斑斑的左轮——和张麻子的是对枪。他喃喃：'John...'",
        "emotional_tone": "震撼、悬念高峰、第一幕转折",
        "key_scenes": ["黄四郎的独处", "那对左轮", "二十年的等待", "身份确认的临界点"]
      }
    ],
    "turning_point": "黄四郎确认张麻子就是约翰·马斯顿，他等了二十年的人终于来了。但他不知道约翰是来找他，还是来杀他。"
  },
  "act_two": {
    "description": "第二幕：子弹飞行（第9-22章，约6-8万字）- 三方智斗升级，身份逐层揭露，兄弟往事浮出水面",
    "key_chapters": [
      {
        "chapter_number": 9,
        "chapter_title": "发钱",
        "core_event": "张麻子发钱给鹅城百姓。黄四郎反击——他发两倍的钱，并附言：'张县长的钱，花着不烫手吗？'",
        "emotional_tone": "博弈、民心争夺",
        "key_scenes": ["发钱场景", "百姓的反应", "黄四郎的反击", "汤师爷的分析"]
      },
      {
        "chapter_number": 10,
        "chapter_title": "夜谈",
        "core_event": "花姐深夜找张麻子。她说出真相的一部分：'亚瑟没死，但他也不是以前的亚瑟了。'",
        "emotional_tone": "沉重、信息量爆炸",
        "key_scenes": ["花姐来访", "关于亚瑟的真相", "二十年前的另一个版本", "约翰的动摇"]
      },
      {
        "chapter_number": 11,
        "chapter_title": "替身",
        "core_event": "张麻子设计抓获黄四郎替身。审讯中替身透露：'真正的黄四郎从不用中国枪，他只用一种枪——左轮。'",
        "emotional_tone": "悬疑、解谜",
        "key_scenes": ["抓替身行动", "审讯场景", "替身的供词", "左轮的线索"]
      },
      {
        "chapter_number": 12,
        "chapter_title": "计划",
        "core_event": "张麻子召集弟兄们开会。他说：'让子弹飞一会儿。'汤师爷翻译：'意思是，等时机成熟。'但只有张麻子知道，他在等黄四郎主动现身。",
        "emotional_tone": "谋划、暗流",
        "key_scenes": ["作战会议", "计划部署", "每个人的任务", "张麻子的真实意图"]
      },
      {
        "chapter_number": 13,
        "chapter_title": "往事（上）",
        "core_event": "回忆章节。二十年前，范·德·林德帮派的最后一夜。达奇的'计划'失败，联邦追兵包围。亚瑟让约翰先走。",
        "emotional_tone": "史诗、悲壮、西部片质感",
        "key_scenes": ["帮派营地", "联邦军围剿", "达奇的疯狂", "亚瑟的选择"]
      },
      {
        "chapter_number": 14,
        "chapter_title": "往事（下）",
        "core_event": "亚瑟断后，被逼入绝境。在悬崖边，他选择跳下——却没有死，而是穿越到了另一个时空。他醒来时，身边是清末的中国。",
        "emotional_tone": "悲剧、命运、转折",
        "key_scenes": ["亚瑟的断后战", "悬崖的选择", "穿越的瞬间", "醒来时的陌生世界"]
      },
      {
        "chapter_number": 15,
        "chapter_title": "黄四郎",
        "core_event": "亚瑟如何在二十年内成为黄四郎。从流浪汉到土匪，从土匪到军阀的座上客，最终成为鹅城之主。他变成了他曾经最痛恨的人。",
        "emotional_tone": "讽刺、黑暗、蜕变",
        "key_scenes": ["亚瑟在清末的挣扎", "第一次杀人（为了生存）", "权力的腐蚀", "黄四郎的诞生"]
      },
      {
        "chapter_number": 16,
        "chapter_title": "对枪",
        "core_event": "张麻子与黄四郎第二次正面交锋。这次没有宴会，只有两人在碉楼天台的对峙。黄四郎掏出那把锈左轮，张麻子瞳孔一缩。",
        "emotional_tone": "高潮、对峙、身份揭露",
        "key_scenes": ["碉楼对峙", "双枪亮相", "兄弟相认", "却无法相拥"]
      },
      {
        "chapter_number": 17,
        "chapter_title": "你是谁",
        "core_event": "亚瑟问：'你来干什么？'约翰答：'找你。'亚瑟笑：'找到了。然后呢？'约翰沉默。",
        "emotional_tone": "对话、灵魂拷问",
        "key_scenes": ["天台对话", "二十年的质问", "各自的变化", "无法回头的路"]
      },
      {
        "chapter_number": 18,
        "chapter_title": "六子的选择",
        "core_event": "六子得知张麻子与黄四郎的关系。他陷入困惑：父亲的敌人，是父亲的兄弟？花姐告诉他更大的真相：'你是约翰的儿子。'",
        "emotional_tone": "身份冲击、青年成长",
        "key_scenes": ["六子的困惑", "花姐揭秘", "血缘真相", "六子的选择"]
      },
      {
        "chapter_number": 19,
        "chapter_title": "汤师爷的翻译",
        "core_event": "汤师爷终于问出口：'张大人，你到底是谁？'张麻子给他讲了一个关于牛仔和土匪的故事。汤师爷听完，愣了半天，然后说：'这他妈是美国话吧？'",
        "emotional_tone": "黑色幽默、解释、信任建立",
        "key_scenes": ["汤师爷的追问", "约翰的故事", "跨文化的解释", "汤师爷的选择"]
      },
      {
        "chapter_number": 20,
        "chapter_title": "达奇的影子",
        "core_event": "黄四郎透露：达奇也穿越了，但去向不明。他可能就在鹅城的某个角落，甚至可能就是三方博弈中的第四方——神秘势力。",
        "emotional_tone": "悬疑加深、新敌人浮现",
        "key_scenes": ["黄四郎的透露", "达奇的去向", "第四方势力", "新的威胁"]
      },
      {
        "chapter_number": 21,
        "chapter_title": "老二之死",
        "core_event": "黄四郎为了逼张麻子离开，杀死了老二。老二临死说：'大哥，我不后悔。'张麻子独自站在尸体前，西部硬汉的眼中终于有了泪。",
        "emotional_tone": "悲剧、愤怒、燃点",
        "key_scenes": ["伏击场景", "老二的牺牲", "张麻子的愤怒", "复仇的火焰"]
      },
      {
        "chapter_number": 22,
        "chapter_title": "最后通牒",
        "core_event": "张麻子给黄四郎下最后通牒：'明天日落，碉楼见。我们了结二十年的账。'黄四郎回复：'好。谁赢谁是黄四郎。'",
        "emotional_tone": "决战前夜、宿命感",
        "key_scenes": ["通牒送达", "双方准备", "各自的回忆", "黎明前的黑暗"]
      }
    ],
    "turning_point": "兄弟身份公开，但二十年的变化让他们无法和解。老二之死成为压垮骆驼的最后一根稻草，约翰决定：就算他是亚瑟，我也要打倒黄四郎。"
  },
  "act_three": {
    "description": "第三幕：子弹落地（第23-30章，约3-4万字）- 碉楼决战，兄弟对决，最终救赎与告别",
    "key_chapters": [
      {
        "chapter_number": 23,
        "chapter_title": "日落之前",
        "core_event": "决战前的最后准备。张麻子、汤师爷、六子各自的行动。花姐揭露最后的秘密：亚瑟当年离开，不是逃跑，是为了引开追兵救约翰。",
        "emotional_tone": "紧张、信息补完、情感铺垫",
        "key_scenes": ["张麻子的准备", "六子与花姐", "真相大白", "救赎的前奏"]
      },
      {
        "chapter_number": 24,
        "chapter_title": "碉楼",
        "core_event": "张麻子带队攻入碉楼。一路血战，暴力美学的极致展现。鹅城百姓终于站出来，跟在张麻子身后冲向碉楼。",
        "emotional_tone": "史诗、热血、群众觉醒",
        "key_scenes": ["攻楼开始", "百姓的觉醒", "暴力美学枪战", "逐层突破"]
      },
      {
        "chapter_number": 25,
        "chapter_title": "达奇现身",
        "core_event": "碉楼顶层，达奇突然出现。他才是幕后黑手——穿越后成为军阀背后的军火商，操纵着鹅城的一切。他的'计划'从未停止。",
        "emotional_tone": "反转、震撼、终极BOSS揭晓",
        "key_scenes": ["达奇现身", "二十年的布局", "真正的敌人", "三人重逢"]
      },
      {
        "chapter_number": 26,
        "chapter_title": "I Had a Plan",
        "core_event": "达奇要求约翰和亚瑟归队，重建帮派，在这个时代称王。约翰拒绝，亚瑟沉默。达奇开枪——打中的是亚瑟。",
        "emotional_tone": "背叛、暴力、选择",
        "key_scenes": ["达奇的提议", "约翰的拒绝", "亚瑟的沉默", "那一枪"]
      },
      {
        "chapter_number": 27,
        "chapter_title": "兄弟",
        "core_event": "约翰与达奇的最终对决。亚瑟重伤倒地，却在关键时刻开枪击伤达奇。兄弟联手的最后一战。",
        "emotional_tone": "燃、热血、兄弟情",
        "key_scenes": ["约翰vs达奇", "亚瑟的援手", "联手一击", "达奇的落败"]
      },
      {
        "chapter_number": 28,
        "chapter_title": "Redemption",
        "core_event": "达奇坠楼前说：'你们永远逃不掉，这个时代和我们的时代一样……'亚瑟补了一枪：'那又怎样。'",
        "emotional_tone": "终结、解脱",
        "key_scenes": ["达奇的遗言", "最后的审判", "帮派时代的终结", "碉楼的黄昏"]
      },
      {
        "chapter_number": 29,
        "chapter_title": "告别",
        "core_event": "亚瑟伤重弥留。他把那把锈左轮交给约翰：'带它回家。'约翰说：'我们一起回。'亚瑟笑：'我已经在家了。'",
        "emotional_tone": "悲壮、温情、告别",
        "key_scenes": ["亚瑟的弥留", "最后的对话", "左轮枪的传承", "兄弟的告别"]
      },
      {
        "chapter_number": 30,
        "chapter_title": "让子弹飞",
        "core_event": "尾声。约翰带着六子、花姐离开鹅城。汤师爷选择留下重建。火车远去，约翰看着窗外的中国大地，喃喃：'We are going home.'六子问：'爹，家在哪？'约翰没有回答，只是把亚瑟的左轮递给他。",
        "emotional_tone": "余韵、希望、开放式结局",
        "key_scenes": ["离开鹅城", "汤师爷的选择", "火车远行", "关于'家'的问答", "左轮枪的传承", "最后一个镜头：两把左轮合二为一"]
      }
    ],
    "turning_point": "达奇才是幕后黑手这一反转，将故事推向终极高潮。兄弟的和解不是通过言语，而是通过并肩作战完成。"
  }
